package com.example.tracking;import com.example.tracking.model.LifecycleEvent;import java.time.Instant;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class LifecycleEventTests{@Test void retainsOrderAndStatus(){var event=new LifecycleEvent("event-1","order-1","customer-1","PAYMENT","COMPLETED",Instant.EPOCH);assertThat(event.orderId()).isEqualTo("order-1");assertThat(event.status()).isEqualTo("COMPLETED");}}
